        id: String? = nil,
        target: String? = nil,
        time: String? = nil,
        dateTime: String? = nil,
        tone: ArenaTone? = nil
    ) {
        self.actor = actor
        self.action = action
        self.id = id
        self.target = target
        self.time = time
        self.dateTime = dateTime
        self.tone = tone
    }
}

