    }
}

/// For a series that IS a state (error rate, pass/fail) rather than an identity. A chart carries identity or meaning, never both; passing tone alongside slot/slots warns in development and tone wins.
public enum ArenaSeriesTone: String, CaseIterable, Sendable {
    case success = "success"
    case warning = "warning"
    case danger = "danger"
    case info = "info"
}

/// Which edge the panel is anchored to. Checked against every enum already declared here before it was added; nothing carries this set. ArenaToastPlacement is the near miss and is a different question: a stack of notices names a CORNER and needs both axes, where a sheet spans the edge it is attached to and names one. There is no top: a panel spanning the top edge of a page is a banner, which is what ArenaAlert already is, and a sheet is a working surface a reader keeps open beside the page. The inline pair is start/end rather than left/right so a right-to-left reading flips it with the document.
public enum ArenaSheetPlacement: String, CaseIterable, Sendable {
    case bottom = "bottom"
    case start = "start"
    case end = "end"
}

/// The shape the placeholder reserves: a single text line, a stack of lines, a block, or a circle.
public enum ArenaSkeletonVariant: String, CaseIterable, Sendable {
    case text = "text"
    case line = "line"
    case block = "block"
    case circle = "circle"
}

/// Which way a column is ordered. Deliberately not ArenaDirection, which is a delta's arrow: up and down say which way a NUMBER moved, and ascending and descending say how a COLUMN is arranged. One set of names for both would read as the same idea in the two places it is not.
public enum ArenaSortDirection: String, CaseIterable, Sendable {
    case asc = "asc"
    case desc = "desc"
}

/// Colour for an indeterminate wait. 'accent' on a page surface, 'on-accent' inside a filled button. There is deliberately no success/warning/danger: a wait has no state to report, and a spinner tinted --danger would read as a failure that has not happened.
public enum ArenaSpinnerTone: String, CaseIterable, Sendable {
    case accent = "accent"
    case gold = "gold"
    case neutral = "neutral"
    case onAccent = "on-accent"
}

/// How a metric moved. Preformatted: ArenaStatCard never formats. The pill's colour says whether the change was GOOD, not which way it points, which is why direction and tone are separate fields.
public struct ArenaStatDelta: Sendable {
    /// Preformatted, e.g. "+12%" or "-340ms".
    public let value: String
    /// Which way the number moved. Draws the arrow: nothing else.
    public let direction: ArenaDirection
    /// Whether that movement is GOOD. Defaults to neutral: an unlabelled delta claims nothing.
    public let tone: ArenaDeltaTone?

    public init(
        value: String,
        direction: ArenaDirection,
        tone: ArenaDeltaTone? = nil
    ) {
        self.value = value
        self.direction = direction
        self.tone = tone
    }
}

/// The switch's overall size, from a dense sm to a prominent 2xl.
public enum ArenaSwitchSize: String, CaseIterable, Sendable {
    case sm = "sm"
    case md = "md"
    case lg = "lg"
    case xl = "xl"
    case size2xl = "2xl"
}

/// How an ArenaTable column's cells render in card mode: `row` is a label/value pair, `block` is a full-width strip with no label whose contents sit at the end of it, which is the shape an actions cell wants. A long value takes `row` or a cell of its own: set to `block` it draws with the whole gap on its leading side. Checked against every enum already declared here; nothing carries this pair. ArenaSkeletonVariant is the only other declaration containing the value `block`, and it names a shape of placeholder rather than a layout.
public enum ArenaTableCellLayout: String, CaseIterable, Sendable {
    case row = "row"
    case block = "block"
}

/// One column's configuration. A column says how its cells are headed and set, never what markup goes in them -- the consumer writes an ArenaTableCell per cell.
public struct ArenaTableColumn: Sendable {
    /// The column's label, drawn in the header row.
    public let header: String
    /// How this column's cells align.
    public let align: ArenaCellAlign?
    /// A fixed width for the column. Omit to let the table distribute.
    public let width: String?
    /// Draw this column's cells in the mono face, figure-aligned, and in the gold ink -- for identifiers and figures. The ink is the half that does not travel outside a table: gold reads as an identifier, so a sale total in gold inside a card says the wrong thing. Each layer offers the face and the digit alignment on their own, for a figure the consumer draws elsewhere, and its usage document says how.
    public let mono: Bool?
    /// Whether this column's header is an activation target. A declared boolean rather than "is sortChange bound?", because Arena never derives what it draws from what a consumer listens for, the same reason ArenaTableRow.interactive is one. It costs no tab stop: the header row is already row 0 of the grid's roving cursor, so a sortable header is activated with Enter or Space on the cell the user is already on. Without ArenaTable.sort no header is a target however many columns declare it, because a control that draws a direction it does not know is worse than no control.
    public let sortable: Bool?
    /// How this column renders in card mode: a label/value pair, or a full-width strip with no label whose contents sit at its end, which suits an actions cell rather than a long value.
    public let mobileLayout: ArenaTableCellLayout?

    public init(
        header: String,
        align: ArenaCellAlign? = nil,
        width: String? = nil,
        mono: Bool? = nil,
        sortable: Bool? = nil,
        mobileLayout: ArenaTableCellLayout? = nil
    ) {
        self.header = header
        self.align = align
        self.width = width
        self.mono = mono
        self.sortable = sortable
        self.mobileLayout = mobileLayout
    }
}

/// Which page of a longer list is on screen. Present, ArenaTable draws its own ArenaPagination below the grid and names it from `label`. ArenaTable does not slice: it does not hold the rows, so the consumer passes the page they already sliced and ArenaTable draws the control over it.
public struct ArenaTablePage: Sendable {
    /// The current page, 1-based, the same counting ArenaPagination uses.
    public let index: Double
    /// How many rows a full page holds. ArenaTable needs it to say how many pages there are, not to cut anything.
    public let size: Double
    /// How many rows there are across every page. Required because the projected children are one page and the count of pages cannot be derived from them; it is also what lets ArenaTable notice that the current page has gone PAST THE END and ask for page 1. That is the only reset ArenaTable performs, and it is the narrower half of the one a consumer writes: filtering ten pages down to five while the reader sits on the third leaves the page in range, so ArenaTable says nothing and the reader is on page three of results they did not ask for. Resetting on every change of total would be wrong, since removing one row from page three of ten must move nobody, and a count alone does not distinguish the two cases. Whether a change of CRITERION returns the reader to the first page is the consumer's question, because the consumer is the one holding the criterion.
    public let total: Double

    public init(
        index: Double,
        size: Double,
        total: Double
    ) {
        self.index = index
        self.size = size
        self.total = total
    }
}

/// Whether ArenaTable draws the pager it knows about. It is an enum rather than a boolean on the ArenaTableSortControl precedent, which this member is the second reading of: how a control is REACHED is a decision with room to grow, and the two members answer the same question about the two things a table's own chrome can hold.
public enum ArenaTablePageControl: String, CaseIterable, Sendable {
    case auto = "auto"
    case none = "none"
}

/// Where the projected rows sit inside a longer list. A reader is told the size of the whole collection and the position of each row within it whenever the rows on screen are only part of it, and a render that projects part of a list is that condition, so this is what those two announcements carry. Bound, it answers them whatever the consumer slices by. Absent with `page` bound, they are derived from the page, because a page IS a slice and stating it twice is how the two disagree. Absent with `page` absent, the projected rows are the whole list and neither is announced, which is the same answer the pattern gives for a grid holding every row it has.
public struct ArenaTableSlice: Sendable {
    /// How many rows the whole list holds, counting the ones nobody projected and not the header row, which ArenaTable adds itself because the announced count includes it. `-1` is the answer for a list whose length is not known yet, and it reaches the announcement unchanged: a feed that loads as it scrolls says -1 rather than a number it would have to invent and correct.
    public let total: Double
    /// How many rows of the whole list come before the first row projected here, counting from 0, so a window at the top of the list passes 0. The announced position is 1-based and the header row takes 1, so ArenaTable does that arithmetic rather than the consumer: an offset that already counted from 1 is counted twice, and the reader is told a position one row past where they are.
    public let offset: Double

    public init(
        total: Double,
        offset: Double
    ) {
        self.total = total
        self.offset = offset
    }
}

/// Which column the rows are ordered by, and which way. Controlled: ArenaTable draws the affordance and announces the order, and the consumer does the ordering, because ArenaTable does not hold the rows and pretending otherwise would be the error. Absent, no header is a sort target however many columns declare `sortable`.
public struct ArenaTableSort: Sendable {
    /// Which column, as its index in `columns`. An index rather than a key, because an ArenaTable's cells are already positional -- the nth ArenaTableCell takes the nth column -- so a key would be a second identity for a thing that already has one, and a required one on every column that a caller would have to invent.
    public let column: Double
    /// Which way that column is ordered.
    public let direction: ArenaSortDirection

    public init(
        column: Double,
        direction: ArenaSortDirection
    ) {
        self.column = column
        self.direction = direction
    }
}

/// How the sort affordance is reached in card mode, where there is no header row to activate. Above --bp-md the header row IS the control and this decides nothing.
public enum ArenaTableSortControl: String, CaseIterable, Sendable {
    case auto = "auto"
    case none = "none"
}

/// The tag's emphasis colour, per the ArenaBadge/ArenaTag tone taxonomy.
public enum ArenaTagTone: String, CaseIterable, Sendable {
    case neutral = "neutral"
    case primary = "primary"
    case success = "success"
    case warning = "warning"
    case danger = "danger"
}

/// Which corner the stack of notices is pinned to, block edge first. Checked against every enum already declared here before it was added; nothing carries this set. ArenaMenuAlign is the near miss and is a different question: it names which edge of a trigger a panel lines up with, on one axis, where this names a corner of the viewport and needs both. The inline half is `start`/`end` rather than left/right so a right-to-left reading flips it with the document.
public enum ArenaToastPlacement: String, CaseIterable, Sendable {
    case topStart = "top-start"
    case topEnd = "top-end"
    case bottomStart = "bottom-start"
    case bottomEnd = "bottom-end"
}

/// The side bar's colour. Narrower than ArenaTone: a toast reports an outcome, and there is no informational outcome a toast should interrupt for.
public enum ArenaToastTone: String, CaseIterable, Sendable {
    case neutral = "neutral"
    case success = "success"
    case danger = "danger"
    case gold = "gold"
}

/// What state a value IS in right now, as against how it moved. ArenaBadge's vocabulary, so one set of tone names covers the system rather than a second set that is nearly the same.
public enum ArenaTone: String, CaseIterable, Sendable {
    case neutral = "neutral"
    case accent = "accent"
    case gold = "gold"
    case success = "success"
    case warning = "warning"
    case danger = "danger"
    case info = "info"
}

/// When ArenaInput runs `validate`: on blur, or on every change.
public enum ArenaValidateOn: String, CaseIterable, Sendable {
    case blur = "blur"
    case change = "change"
}
